<script lang="ts">import{JobJournal}from'../jobs.js';import type{EditorDatabase,PersistedJob}from'../persistence/database.js';export let database:EditorDatabase;export let onRetry:(job:PersistedJob)=>void=()=>{};let jobs:PersistedJob[]=[];let loaded=false;async function refresh(){jobs=await new JobJournal(database).recover();loaded=true}function retry(job:PersistedJob){if(!confirm('The printer may already have accepted part of this job. Check the physical output. Start a new explicit print attempt?'))return;onRetry(job)}
</script>
<section><h2>Recover print jobs</h2>{#if !loaded}<button on:click={refresh}>Check interrupted jobs</button>{:else if !jobs.length}<p>No ambiguous jobs.</p>{:else}<ul>{#each jobs as job}<li><strong>{job.state}</strong><small>{new Date(job.createdAt).toLocaleString()} · {job.route}</small><p>The outcome is uncertain. Never assume the label was retracted or automatically replay it.</p><button on:click={()=>retry(job)}>Inspect & explicitly retry</button></li>{/each}</ul>{/if}</section><style>section{padding:.7rem .75rem;border-top:1px solid var(--mble-border,#e5dfd5)}h2{margin:0 0 .5rem;color:var(--mble-text-muted,#59635e);font-size:.75rem;font-weight:600}ul{list-style:none;padding:0}li{border-left:3px solid var(--mble-primary,#ed6146);padding:.4rem;margin:.4rem 0}small{display:block}</style>
